mapper.update:
UPDATE dms_shop_order
SET status = #{status}, update_time = CURRENT_TIMESTAMP
WHERE id = #{id} AND COALESCE(tenant_id, 1) = #{tenantId}

UPDATE dms_shop_order SET status = 1,
pay_type = #{payType},
pay_time = CURRENT_TIMESTAMP, update_time = CURRENT_TIMESTAMP WHERE id = #{id} AND status = 0 AND COALESCE(tenant_id, 1) = #{tenantId}

UPDATE dms_shop_order
SET service_remark=#{serviceRemark}, update_time=CURRENT_TIMESTAMP
WHERE id=#{id} AND COALESCE(tenant_id, 1) = #{tenantId}

mapper.select:
SELECT id
FROM dms_shop_order
WHERE status = 0 AND create_time <= #{cutoffTime}
ORDER BY create_time ASC, id ASC
LIMIT #{limit}
